  \coordinate (B) at (-3.456, 2.070);
  \coordinate (C) at ( 3.456, 2.070);
  \coordinate (Q) at ( 3.456,-2.070);
  \coordinate (P) at (-3.456, 0.000);

  % Solid segments
  \draw (A) -- (B);
  \draw (B) -- (C);
  \draw (C) -- (Q);
  \draw (Q) -- (A);
  \draw (P) -- (Q);

  % Filled dots at the five vertices
