  \node[below, font=\fontsize{14.5}{17.4}\selectfont] at (A) {$A$};
  \node[below, font=\fontsize{14.5}{17.4}\selectfont] at (Q) {$Q$};
  \node[left, font=\fontsize{14.5}{17.4}\selectfont] at (P) {$P$};
